// Local SignalRGB -> PNY Color bridge. No I2C/SMBus or GPU access here.
// Uses the network/UDP API of the installed SignalRGB WLED plugin.
import udp from "@SignalRGB/udp";

export function Name() { return "PNY Color Bridge"; }
export function Version() { return "1.1.0"; }
export function Publisher() { return "PNY Color local project"; }
export function Type() { return "network"; }
// This is a virtual network device, not SignalRGB's native GPU/SMBus interface.
export function Size() { return [1, 1]; }
export function DefaultPosition() { return [5, 2]; }
export function DefaultScale() { return 2.5; }
export function LedNames() { return ["PNY UPRISING RGB"]; }
export function LedPositions() { return [[0, 0]]; }
export function ControllableParameters() {
    return [
        { property: "lightingMode", group: "lighting", label: "Origem da cor", type: "combobox", values: ["Canvas", "Cor fixa"], default: "Canvas" },
        { property: "forcedColor", group: "lighting", label: "Cor fixa", type: "color", default: "#FF8000" }
    ];
}

const HOST = "127.0.0.1";
const PORT = 39841;
const ID = "pny-color-local-1384196e";
const COVER_BASE64 = "";
let socket;
let lastAt = -Infinity;
let lastKey = "";

export function Initialize() {
    device.setName("PNY RTX 3080 Ti — ponte local");
    device.setImageFromBase64(COVER_BASE64);
    socket = udp.createSocket();
    lastAt = -Infinity;
    lastKey = "";
    device.log("Ponte local: selecione SignalRGB no PNY Color e clique em Aplicar.");
}

function rgbValue() {
    if (typeof lightingMode !== "undefined" && lightingMode === "Cor fixa") {
        const value = typeof forcedColor === "string" ? forcedColor : "";
        const match = /^#?([0-9a-f]{6})$/i.exec(value);
        if (!match) return null;
        const packed = parseInt(match[1], 16);
        return [(packed >>> 16) & 255, (packed >>> 8) & 255, packed & 255];
    }
    return device.color(0, 0);
}

export function Render() {
    if (!socket) return;
    const now = Date.now();
    if (now >= lastAt && now - lastAt < 100) return;
    const color = rgbValue();
    if (!color || color.length < 3) return;
    const rgb = Array.from(color).slice(0, 3);
    if (rgb.some(value => !Number.isFinite(value) || value < 0 || value > 255)) return;
    const bytes = rgb.map(value => Math.round(value));
    // Board-specific behavior reported by the user: RGB 0,0,0 starts its
    // internal color cycle. Hold the last color until a true OFF path is verified.
    if (bytes.every(value => value === 0)) return;
    const key = bytes.join(",");
    // Heartbeat lets the receiver distinguish a steady color from disconnection.
    if (key === lastKey && now >= lastAt && now - lastAt < 1000) return;
    socket.write([80, 78, 89, 49, bytes[0], bytes[1], bytes[2], 100], HOST, PORT);
    lastAt = now;
    lastKey = key;
}

export function Shutdown() {
    // Leave the final color in place; do not blank the board on plugin reload.
    if (socket) socket.close();
    socket = undefined;
}

export function DiscoveryService() {
    let announced = false;
    this.Initialize = function() {
        if (announced) return;
        const local = {
            id: ID,
            name: "PNY RTX 3080 Ti — ponte local",
            hostname: HOST,
            ip: HOST,
            port: PORT,
            connected: true
        };
        if (service.getController(ID) === undefined) service.addController(local);
        service.announceController(local);
        announced = true;
        service.log("Ponte PNY anunciada. Transporte restrito a 127.0.0.1:39841.");
    };
    this.Update = function() {};
}
